import sys, numpy as np
from robot import tools, handoff
from ora_lib import current
import geo

arm, bname, wname = sys.argv[1], sys.argv[2], sys.argv[3]
obs = current()
bb = geo.bottle_now(obs, bname)
if bb is None: handoff("bottle not grounded", bname=bname)
bw = geo.bowl_now(obs, wname)
wx, wy, rimz, wr = geo.BOWL_FIXED[wname]
if bw is not None and (abs(bw["x"]-wx) > 0.02 or abs(bw["y"]-wy) > 0.02):
    handoff("bowl moved from its measured place", fresh=[bw["x"],bw["y"]], fixed=[wx,wy])
bx, by, ztop = bb["x"], bb["y"], bb["ztop"]
print(f"bottle {bname} axis ({bx:.4f},{by:.4f}) top {ztop:.4f} bbox {bb['bbox']} | bowl {wname} ({wx:.4f},{wy:.4f}) rim {rimz:.4f}")
if abs(ztop - 0.9838) > 0.02: handoff("bottle top unexpected", ztop=ztop)

GZ, APP = geo.GRASP_GZ, geo.JAW_CENTRE_ALONG_APPROACH
p_grasp = [bx, by - APP, GZ]
p_pre   = [bx, by - APP - 0.12, GZ + 0.06]
def tgt(p, it):
    return {arm: {"position_mode": "absolute", "position_m": [float(v) for v in p],
                  "orientation_mode": "hold_current", "interaction": it}}
for name, p, it in (("pregrasp", p_pre, "free_space"), ("grasp", p_grasp, "precision")):
    pl = tools.move_pose(targets=tgt(p, it), dry_run=True)
    print("dry", name, pl.feasible, pl.failure_code, "|", (pl.summary or "")[:110])
    if not pl.feasible: handoff("approach not plannable", stage=name, code=pl.failure_code)
r = tools.move_pose(targets=tgt(p_pre, "free_space"));  print("pregrasp", r.status, r.ok)
if not r.ok: handoff("pregrasp failed", code=r.failure_code)
r = tools.move_pose(targets=tgt(p_grasp, "precision")); print("approach", r.status, r.ok)
if not r.ok: handoff("approach failed", code=r.failure_code)
r = tools.set_gripper(targets={arm: "close"}); print("close", r.status, r.measured_opening)
r = tools.move_pose(targets=tgt([bx, by-APP, GZ+0.08], "precision")); print("lift", r.status, r.ok)
if not r.ok: handoff("lift failed", code=r.failure_code)
obs2 = current()
p_after = obs2.pose(arm)
print("arm after lift", np.round(p_after.xyz,4).tolist())
bb2 = geo.bottle_now(obs2, bname)
print("bottle now", None if bb2 is None else (round(bb2["x"],4), round(bb2["y"],4), round(bb2["ztop"],4)), "expected top", round(ztop+0.08,4))
if bb2 is None or bb2["ztop"] < ztop + 0.05:
    handoff("bottle did not rise with the gripper", measured=None if bb2 is None else bb2["ztop"])
print("grasp ok")

